use clap::{Parser, Subcommand};
use std::net::IpAddr;
use tracing::{info, warn, instrument};

const CONTROL_PORT: u16 = 7835;
const MAX_TCP_PORT: u16 = 65535;

#[derive(Parser, Debug)]
#[command(name = "bore-cli")]
#[command(version = "0.6.0")]
#[command(about = "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Starts a local proxy to the remote server
    Local(LocalArgs),
    /// Runs the remote proxy server
    Server(ServerArgs),
}

#[derive(Parser, Debug)]
struct LocalArgs {
    /// The local port to expose
    #[arg(env = "BORE_LOCAL_PORT")]
    local_port: u16,

    /// The local host to expose
    #[arg(short = 'l', long = "local-host", default_value = "localhost")]
    local_host: String,

    /// Address of the remote server to expose local ports to
    #[arg(short = 't', long = "to", env = "BORE_SERVER")]
    to: String,

    /// Optional port on the remote server to select
    #[arg(short = 'p', long = "port", default_value = "0")]
    port: u16,

    /// Optional secret for authentication
    #[arg(short = 's', long = "secret", env = "BORE_SECRET")]
    secret: Option<String>,
}

#[derive(Parser, Debug)]
struct ServerArgs {
    /// Minimum accepted TCP port number
    #[arg(long = "min-port", env = "BORE_MIN_PORT", default_value = "1024")]
    min_port: u16,

    /// Maximum accepted TCP port number
    #[arg(long = "max-port", env = "BORE_MAX_PORT", default_value = "65535")]
    max_port: u16,

    /// Optional secret for authentication
    #[arg(short = 's', long = "secret", env = "BORE_SECRET")]
    secret: Option<String>,

    /// IP address to bind to, clients must reach this
    #[arg(long = "bind-addr", default_value = "0.0.0.0")]
    bind_addr: IpAddr,

    /// IP address where tunnels will listen on, defaults to --bind-addr
    #[arg(long = "bind-tunnels")]
    bind_tunnels: Option<IpAddr>,
}

mod protocol {
    use serde::{Deserialize, Serialize};
    use uuid::Uuid;

    #[derive(Serialize, Deserialize, Debug, Clone)]
    pub enum Message {
        Hello(u16),
        Challenge(Uuid),
        Authenticate(String),
        Accept(Uuid),
        Connection(Uuid),
        Heartbeat,
        Error(String),
    }

    // Helper to parse message string that may be json string "Heartbeat" or object
    // serde will handle both variants correctly if we use untagged? Actually our enum representation matches the observed JSON:
    // {"Hello":0}, {"Challenge":"uuid"}, {"Authenticate":"..."}, {"Accept":"uuid"}, {"Connection":"uuid"}, "Heartbeat", {"Error":"..."}
    // So we need to use serde that can handle string variant "Heartbeat" as unit-like? But observed Heartbeat is JSON string "Heartbeat"
    // Our enum with variant Heartbeat would serialize as "Heartbeat" (string) if we use #[serde(other)]? Actually serde will serialize Unit variant as string? Let's check.
    // For enum Message, serde by default will serialize unit variant as string? Actually with internally tagged? We need to match the existing protocol which uses either:
    // For Hello: object {"Hello": port}
    // For Authenticate: {"Authenticate": "..."}
    // etc.
    // And Heartbeat: "Heartbeat" (a JSON string, not object)
    // The default serde for enum without tag will serialize as: external tagging: Hello -> {"Hello": port}, Heartbeat -> "Heartbeat" (string). That matches!
    // So we can just use default.
}

mod common {
    use anyhow::Result;
    use serde_json;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};

    use super::protocol::Message;

    pub async fn read_message<R>(reader: &mut R) -> Result<Option<Message>>
    where
        R: AsyncReadExt + Unpin,
    {
        let mut buf = Vec::new();
        loop {
            let mut byte = [0u8; 1];
            let n = reader.read(&mut byte).await?;
            if n == 0 {
                if buf.is_empty() {
                    return Ok(None);
                } else {
                    return Err(anyhow::anyhow!("connection closed before null byte"));
                }
            }
            if byte[0] == 0 {
                break;
            }
            buf.push(byte[0]);
        }
        if buf.is_empty() {
            // empty message? Skip? Treat as None?
            // In bore, double null shouldn't happen, but we treat as continuing?
            return Ok(None);
        }
        let msg: Message = serde_json::from_slice(&buf)?;
        Ok(Some(msg))
    }

    pub async fn write_message<W>(writer: &mut W, msg: &Message) -> Result<()>
    where
        W: AsyncWriteExt + Unpin,
    {
        let json = serde_json::to_string(msg)?;
        writer.write_all(json.as_bytes()).await?;
        writer.write_all(&[0]).await?;
        Ok(())
    }

    pub async fn write_message_and_flush<W>(writer: &mut W, msg: &Message) -> Result<()>
    where
        W: AsyncWriteExt + Unpin,
    {
        write_message(writer, msg).await?;
        writer.flush().await?;
        Ok(())
    }
}

mod auth {
    use hmac::{Hmac, Mac};
    use sha2::{Digest, Sha256};
    use uuid::Uuid;

    type HmacSha256 = Hmac<Sha256>;

    pub fn answer(challenge: &Uuid, secret: &str) -> String {
        let hashed_secret = Sha256::digest(secret.as_bytes());
        let mut mac = HmacSha256::new_from_slice(&hashed_secret).expect("HMAC can take key of any size");
        mac.update(challenge.as_bytes());
        let result = mac.finalize().into_bytes();
        hex::encode(result)
    }

    pub fn verify(challenge: &Uuid, secret: &str, response: &str) -> bool {
        let expected = answer(challenge, secret);
        expected == response
    }
}

mod server {
    use super::auth;
    use super::common;
    use super::protocol::Message;
    use anyhow::{anyhow, Context, Result};
    use std::collections::HashMap;
    use std::net::{IpAddr, SocketAddr};
    use std::sync::Arc;
    use tokio::io::{AsyncRead, AsyncWrite};
    use tokio::net::{TcpListener, TcpStream};
    use tokio::sync::Mutex;
    use tracing::{info, warn, instrument};
    use uuid::Uuid;

    struct Client {
        remote_port: u16,
        tunnel_listener: Option<TcpListener>,
    }

    struct SharedState {
        clients: HashMap<u16, ()>, // just track used ports
        // For connection forwarding, we need to map connection id to a TcpStream that is the incoming public connection waiting?
        // Actually server's logic:
        // - Control connection: after handshake, server holds control TcpStream and also creates a TcpListener on bind_tunnels:remote_port.
        // - When a remote connection arrives to that listener, server generates a UUID, sends Message::Connection(uuid) over control channel.
        // - Then it waits for client to open a new control connection and send Message::Accept(uuid).
        // - Then server needs to pair the public TcpStream with the client's new Accept stream, and proxy.
        // So we need to store pending connections.

        // Map connection id -> public TcpStream (or its reader/writer) waiting to be proxied
        pending: HashMap<Uuid, TcpStream>,
    }

    pub struct Server {
        min_port: u16,
        max_port: u16,
        secret: Option<String>,
        bind_addr: IpAddr,
        bind_tunnels: IpAddr,
    }

    impl Server {
        pub fn new(min_port: u16, max_port: u16, secret: Option<String>, bind_addr: IpAddr, bind_tunnels: Option<IpAddr>) -> Result<Self> {
            if min_port > max_port {
                return Err(anyhow!("port range is empty"));
            }
            let bind_tunnels = bind_tunnels.unwrap_or(bind_addr);
            Ok(Self {
                min_port,
                max_port,
                secret,
                bind_addr,
                bind_tunnels,
            })
        }

        pub async fn run(self) -> Result<()> {
            if self.min_port > self.max_port {
                return Err(anyhow!("port range is empty"));
            }
            let control_addr = SocketAddr::new(self.bind_addr, super::CONTROL_PORT);
            let listener = TcpListener::bind(control_addr).await.context("failed to bind control listener")?;
            info!(addr = %self.bind_addr, "server listening");

            let shared = Arc::new(Mutex::new(SharedState {
                clients: HashMap::new(),
                pending: HashMap::new(),
            }));

            loop {
                let (stream, addr) = listener.accept().await?;
                let secret = self.secret.clone();
                let shared_clone = shared.clone();
                let min_port = self.min_port;
                let max_port = self.max_port;
                let bind_tunnels = self.bind_tunnels;
                let bind_addr_for_log = self.bind_addr; // not needed
                tokio::spawn(async move {
                    if let Err(e) = handle_control(stream, addr, secret, shared_clone, min_port, max_port, bind_tunnels).await {
                        // Don't log errors that are not critical? But original bore logs handshake failed as warn
                        // For simplicity, just handle
                    }
                });
            }
        }
    }

    #[instrument(skip(stream, shared))]
    async fn handle_control(
        mut stream: TcpStream,
        addr: SocketAddr,
        secret: Option<String>,
        shared: Arc<Mutex<SharedState>>,
        min_port: u16,
        max_port: u16,
        bind_tunnels: IpAddr,
    ) -> Result<()> {
        info!(%addr, "incoming connection");
        // Handshake
        // Timeout settings from original bore: 3 seconds? Let's observe. Our earlier tests showed 3 seconds timeout waiting for initial message.
        // Client behavior:
        // - If secret is None: client sends Hello(port) and expects Hello(port) back.
        // - If secret is Some: server first sends Challenge, expects Authenticate, then Hello.
        // Wait, looking at MITM traces:
        // For server with secret:
        //  - Server on accept immediately sends Challenge before receiving Hello.
        //  - Then client sends Authenticate + Hello (could be in same packet or separate).
        //  - We saw: S->C Challenge, then C->S Authenticate + Hello, then S->C Hello + Heartbeat.

        // For server without secret:
        //  - Server waits for Hello from client (3 sec timeout)
        //  - Then server responds with Hello(allocated_port).

        // However there is nuance for client that has secret but server doesn't: 
        // Client with secret waits for Challenge, but server without secret waits for Hello -> deadlock and both timeout after 3 sec.
        // Our earlier test of client with secret to server without secret resulted in: client error "timed out waiting for initial message" and server log "timed out waiting for initial message".
        // That matches: server without secret waits for Hello; client with secret waits for Challenge; both timeout.

        // For server with secret, client without secret: 
        // Client sends Hello (0)
        // Server sends Challenge immediately (without waiting for Hello?), but our earlier capture shows when client without secret connects to secret server, server sends Challenge immediately before receiving Hello? Let's see logs from earlier capture:
        // For raw test: client sends Hello:0, server replies Challenge then Error after second recv. Actually first test showed: client sends Hello:0, server sends Challenge, then Error "server requires secret, but no secret was provided" without waiting 3 sec. So server must have received Hello first, then sent Challenge, then waited for Auth but got none? No, in that trace, client sent Hello, server sent Challenge, then server immediately sent Error after receiving ??? Let's check raw flow earlier:
        // In test_raw_hello first case (server secret, client sends Hello:0 only): 
        //   client sent Hello, server sent Challenge + Error immediately.
        // Actually log: recv Challenge, then part Error. So server sent Challenge, then Error in quick succession, without waiting 3 sec for Auth? But maybe it waited 3 sec for Auth and then sent Error? However our timeout test showed when we didn't send Auth, server waited 3 sec then sent Error "timed out waiting for initial message". Wait that is different.
        // Let's re-evaluate:
        // In test_raw_hello we saw: after Hello, immediate Challenge + Error "server requires secret, but no secret was provided" (no 3 sec wait). That indicates if client sends Hello but no Auth, server detects missing Auth and sends that error immediately.
        // But in timeout test where we didn't send anything after receiving Challenge, server sent "timed out waiting for initial message" after 3 sec.
        // So server logic:
        // - Upon new connection, if secret is Some:
        //   - Generate challenge UUID, send Challenge.
        //   - Wait for Authenticate message (with timeout 3 sec?)
        //   - If no Auth received and client sent Hello first, then error "server requires secret, but no secret was provided"
        //   - If Auth received and valid, proceed to wait for Hello?
        // Actually in earlier MITM we observed correct order: Challenge first, then client sends Auth + Hello. Server didn't wait for Hello before Challenge. So server sends Challenge immediately on connect, regardless of Hello.
        // But then what about client without secret? It sends Hello first. Server receives Hello, but because secret is required, it still had already sent Challenge; then it should check if client also sent Auth? In our raw test, client sent Hello only, server had already sent Challenge, then after receiving Hello, it sent Error about missing secret immediately (not waiting for Auth). Could be because server's state after sending Challenge expects either Authenticate or Hello? If it gets Hello before Auth, it knows client didn't provide secret.
        // Let's look at bore source memory: I think protocol is:
        // Server:
        //   if secret.is_some():
        //     send Challenge
        //     read message (expect Authenticate)
        //     verify, if fails -> send Error("invalid secret") and close
        //     if no Auth but got Hello -> Error("server requires secret, but no secret was provided")
        //   then read Hello
        // Client:
        //   if secret.is_some():
        //     wait for Challenge (with timeout)
        //     send Authenticate
        //     then send Hello
        //     wait for Hello response
        //   else:
        //     send Hello
        //     wait for Hello or Challenge?
        //     If receives Challenge, then error "server requires authentication, but no client secret was provided"
        //     If receives Hello, success
        //     If timeout, error "timed out waiting for initial message"

        // For server without secret:
        //   wait for Hello (timeout 3 sec)
        //   if receives Challenge? (shouldn't happen) But if client has secret, client waits for Challenge and doesn't send Hello, so server times out -> "timed out waiting for initial message"
        //   if receives Hello, allocate port and send Hello back.

        // Let's implement both with timeout 3 sec for initial message reading.

        use tokio::time::{timeout, Duration};

        const HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(3);
        // Helper closure to read with timeout
        async fn read_with_timeout<S>(s: &mut S) -> Result<Option<Message>>
        where
            S: AsyncRead + Unpin,
        {
            match timeout(HANDSHAKE_TIMEOUT, super::common::read_message(s)).await {
                Ok(res) => res,
                Err(_) => Err(anyhow!("timed out waiting for initial message")),
            }
        }

        if let Some(secret_value) = secret.clone() {
            // Secret required
            let challenge = Uuid::new_v4();
            common::write_message_and_flush(&mut stream, &Message::Challenge(challenge)).await?;

            // Wait for first message from client
            let first_msg = match read_with_timeout(&mut stream).await {
                Ok(m) => m,
                Err(e) => {
                    // Timeout case: server already sent Challenge, now times out waiting for Auth
                    // In our earlier observation, when client didn't send Auth, server sent Error "timed out waiting for initial message" after 3 sec
                    // So we should send that error if it's timeout error
                    let err_msg = e.to_string();
                    // Try to send Error message with same text?
                    // But for generic timeout, original bore logs "timed out waiting for initial message" and sends same as JSON error?
                    // In our earlier capture, after timeout without auth, server sent {"Error":"timed out waiting for initial message"}?
                    // Actually in timeout_test we saw more data: {"Error":"timed out waiting for initial message"} after challenge.
                    // So we should send Error with err_msg
                    let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_msg.clone())).await;
                    warn!(err = %err_msg, "server handshake failed");
                    return Err(anyhow!(err_msg));
                }
            };

            let auth_msg = match first_msg {
                Some(Message::Authenticate(token)) => token,
                Some(Message::Hello(_)) => {
                    // Client sent Hello but didn't authenticate
                    let err_str = "server requires secret, but no secret was provided".to_string();
                    let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_str.clone())).await;
                    warn!(err = %err_str, "server handshake failed");
                    return Err(anyhow!(err_str));
                }
                Some(other) => {
                    // Unexpected message, treat as invalid?
                    let err_str = format!("unexpected message {:?}", other);
                    let _ = common::write_message_and_flush(&mut stream, &Message::Error("invalid secret".to_string())).await;
                    warn!(err = %err_str, "server handshake failed");
                    return Err(anyhow!(err_str));
                }
                None => {
                    // connection closed
                    return Err(anyhow!("connection closed"));
                }
            };

            // Verify auth
            if !auth::verify(&challenge, &secret_value, &auth_msg) {
                let err_str = "invalid secret".to_string();
                let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_str.clone())).await;
                warn!(err = %err_str, "server handshake failed");
                return Err(anyhow!(err_str));
            }

            // Auth ok, now wait for Hello
            let hello_msg = match read_with_timeout(&mut stream).await {
                Ok(m) => m,
                Err(e) => {
                    let err_str = e.to_string();
                    let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_str.clone())).await;
                    warn!(err = %err_str, "server handshake failed");
                    return Err(anyhow!(err_str));
                }
            };

            let requested_port = match hello_msg {
                Some(Message::Hello(p)) => p,
                Some(other) => {
                    let err_str = format!("expected Hello, got {:?}", other);
                    return Err(anyhow!(err_str));
                }
                None => return Err(anyhow!("connection closed")),
            };

            // Validate and allocate port
            let allocated = allocate_port(requested_port, min_port, max_port, bind_tunnels, shared.clone()).await?;

            // Success response
            common::write_message_and_flush(&mut stream, &Message::Hello(allocated)).await?;
            info!(host = %bind_tunnels, port = allocated, "new client");

            // Now enter loop for managing this control connection
            // We need to spawn tunnel listener and heartbeat sender
            handle_client_after_handshake(stream, addr, allocated, bind_tunnels, shared).await?;

        } else {
            // No secret
            let first_msg = match read_with_timeout(&mut stream).await {
                Ok(m) => m,
                Err(e) => {
                    // Timeout
                    warn!(err = %e.to_string(), "connection exited with error");
                    return Err(anyhow!(e));
                }
            };

            let requested_port = match first_msg {
                Some(Message::Hello(p)) => p,
                Some(Message::Challenge(_)) => {
                    // Should not happen, server no secret shouldn't send challenge
                    // But client with secret expects challenge; we are no secret case.
                    // Actually we are server without secret, if we receive Challenge? No.
                    // This branch for unexpected messages - close.
                    return Err(anyhow!("unexpected Challenge"));
                }
                Some(Message::Authenticate(_)) => {
                    // Client sent Auth but server doesn't require secret. Original bore behavior: client times out waiting for initial message.
                    // Server without secret, when it receives Authenticate? Let's see earlier test: server no secret, client with secret: client sent nothing? Actually we didn't capture. We saw server times out waiting for initial message.
                    // What should server do when it receives Authenticate but no secret?
                    // Looking at bore source guess: server would treat any non-Hello as error and close, but client is waiting for Challenge which never comes, so timeout.
                    // To reproduce the "timed out waiting for initial message" on client side, server should NOT send any response to Auth? But our earlier MITM showed when server no secret and client with secret, server received nothing? Actually client with secret waits for Challenge and doesn't send anything, so server times out waiting for Hello.
                    // So receiving Authenticate when no secret is unexpected; we should just close without sending.
                    // However we need to check what happens if client with secret sends Auth without Challenge (shouldn't).
                    // For simplicity, if we receive Auth here, we timeout? Let's just return error.
                    warn!("server handshake failed: unexpected auth");
                    return Err(anyhow!("unexpected auth"));
                }
                Some(other) => {
                    return Err(anyhow!("expected Hello, got {:?}", other));
                }
                None => return Err(anyhow!("connection closed")),
            };

            // Allocate port
            let allocated = allocate_port(requested_port, min_port, max_port, bind_tunnels, shared.clone()).await?;

            // Send Hello back
            common::write_message_and_flush(&mut stream, &Message::Hello(allocated)).await?;
            info!(host = %bind_tunnels, port = allocated, "new client");

            // Handle after handshake
            handle_client_after_handshake(stream, addr, allocated, bind_tunnels, shared).await?;
        }

        Ok(())
    }

    async fn allocate_port(
        requested: u16,
        min_port: u16,
        max_port: u16,
        bind_tunnels: IpAddr,
        shared: Arc<Mutex<SharedState>>,
    ) -> Result<u16> {
        // If requested == 0, choose random port in range
        // Else, ensure requested is in allowed range and not already used, then use it.
        // If requested !=0 and not in range -> error "client port number not in allowed range"
        // If requested !=0 and already in use -> error "port already in use"

        if requested != 0 {
            if requested < min_port || requested > max_port {
                return Err(anyhow!("client port number not in allowed range"));
            }
            // Check if already used
            let mut s = shared.lock().await;
            if s.clients.contains_key(&requested) {
                return Err(anyhow!("port already in use"));
            }
            // Try to bind to test if port is available? Original bore tries to bind and if fails, returns port already in use.
            // We'll attempt to bind to allocated port to see if it's free, but we actually will bind later.
            // For now, insert placeholder to reserve
            // But we need to ensure OS port free. We'll let later listener bind fail handle.
            // Reserve now to avoid race
            s.clients.insert(requested, ());
            drop(s);
            // Try bind
            let addr = SocketAddr::new(bind_tunnels, requested);
            match TcpListener::bind(addr).await {
                Ok(listener) => {
                    // Keep listener? Actually allocate_port should return listener? In our design, handle_client_after_handshake will create its own listener.
                    // So we released lock and bound, we need to return port but also need to ensure listener not dropped.
                    // For simplicity, we will NOT bind here, but instead let handle_client_after_handshake bind; if fails, we remove reservation and return error "port already in use"
                    // So to avoid double bind, we don't bind here, just reserve
                    // But we already inserted, so need to keep it.
                    // However we tried to bind above to check OS availability, we should drop listener and let next bind again. So it's okay.
                    drop(listener);
                    Ok(requested)
                }
                Err(e) => {
                    // Remove reservation
                    let mut s = shared.lock().await;
                    s.clients.remove(&requested);
                    // Check if error is AddrInUse -> map to port already in use, else other error
                    Err(anyhow!("port already in use"))
                }
            }
        } else {
