mod common {
    use super::protocol::Message;
    use anyhow::Result;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};

    pub async fn read_message<R>(reader: &mut R) -> Result<Option<Message>>
    where
        R: AsyncReadExt + Unpin,
    {
        let mut buf = Vec::new();
        loop {
            let mut byte = [0u8; 1];
            let n = reader.read(&mut byte).await?;
            if n == 0 {
                if buf.is_empty() {
                    return Ok(None);
                } else {
                    return Err(anyhow::anyhow!("connection closed before null byte"));
                }
            }
            if byte[0] == 0 {
                break;
            }
            buf.push(byte[0]);
        }
        if buf.is_empty() {
            return Ok(None);
        }
        let msg: Message = serde_json::from_slice(&buf)?;
        Ok(Some(msg))
    }

    pub async fn write_message<W>(writer: &mut W, msg: &Message) -> Result<()>
    where
        W: AsyncWriteExt + Unpin,
    {
        let json = serde_json::to_string(msg)?;
        writer.write_all(json.as_bytes()).await?;
        writer.write_all(&[0]).await?;
        Ok(())
    }

    pub async fn write_message_and_flush<W>(writer: &mut W, msg: &Message) -> Result<()>
    where
        W: AsyncWriteExt + Unpin,
    {
        write_message(writer, msg).await?;
        writer.flush().await?;
        Ok(())
    }
