                    // Accept without secret? In no-secret mode, proxy connections also send Accept without prior Challenge.
                    // Handle it.
                    handle_accept(stream, addr, uuid, shared).await?;
                }
                Some(Message::Authenticate(_)) => {
                    // Client has secret but server doesn't. According to earlier behavior, server will timeout waiting for initial message?
                    // Actually client with secret waits for Challenge; server without secret waits for Hello. So client hasn't sent anything yet? But if it did send Auth, that's unexpected.
                    // To reproduce original behavior "timed out waiting for initial message" on client side, server should NOT respond and just wait for Hello, eventually timeout.
                    // So receiving Auth here is not expected; we should treat as if client didn't send Hello and wait? But we already received a message, so it's not timeout.
                    // In earlier test, client with secret to server without secret: MITM showed client closed without sending? Wait earlier MITM test (fake server no secret) showed client with secret didn't send anything, it waited for Challenge. So first_msg would timeout, not be Auth.
                    // So this branch (Authenticate received) shouldn't happen in that scenario.
                    // For robustness, if we do receive Auth, we should ignore and then error?
                    warn!("unexpected Authenticate when no secret required");
                    return Err(anyhow!("unexpected auth"));
                }
                Some(other) => {
                    warn!(?other, "unexpected message");
                    return Err(anyhow!("unexpected message"));
                }
                None => return Err(anyhow!("connection closed")),
            }
        }

        Ok(())
    }

    async fn handle_new_client(
        stream: TcpStream,
        _addr: SocketAddr,
        requested_port: u16,
        config: ServerConfig,
        shared: Arc<Mutex<SharedState>>,
    ) -> Result<()> {
        // Allocate port and start tunnel listener loop
        let allocated = {
            // validation and reservation
            if requested_port != 0 {
                if requested_port < config.min_port || requested_port > config.max_port {
                    let mut s = stream;
                    let _ = common::write_message_and_flush(&mut s, &Message::Error("client port number not in allowed range".to_string())).await;
                    return Err(anyhow!("client port number not in allowed range"));
                }
                let mut state = shared.lock().await;
                if state.allocated_ports.contains_key(&requested_port) {
                    drop(state);
                    let mut s = stream;
                    let _ = common::write_message_and_flush(&mut s, &Message::Error("port already in use".to_string())).await;
                    return Err(anyhow!("port already in use"));
                }
                // Try to bind to check availability (will bind again later, but okay)
                let bind_addr = SocketAddr::new(config.bind_tunnels, requested_port);
                match TcpListener::bind(bind_addr).await {
                    Ok(l) => {
                        // reserve and drop listener (we will bind again in run_client)
                        drop(l);
                        state.allocated_ports.insert(requested_port, ());
                        requested_port
                    }
                    Err(_) => {
                        drop(state);
                        let mut s = stream;
                        let _ = common::write_message_and_flush(&mut s, &Message::Error("port already in use".to_string())).await;
                        return Err(anyhow!("port already in use"));
                    }
                }
            } else {
                // random port
                let mut attempts = 0;
                let mut chosen = None;
                loop {
                    let candidate = if config.min_port == 0 && config.max_port == 65535 {
                        0
                    } else {
                        // try random-ish: incremental
                        if attempts < (config.max_port - config.min_port + 1) as usize {
                            config.min_port + (attempts as u16 % (config.max_port - config.min_port + 1))
                        } else {
                            0 // fallback to OS random
                        }
                    };

                    // check if candidate already allocated (when candidate !=0)
                    if candidate != 0 {
                        let state = shared.lock().await;
                        if state.allocated_ports.contains_key(&candidate) {
                            attempts += 1;
                            if attempts > 10000 {
                                break;
                            }
                            continue;
                        }
                    }

                    let bind_addr = SocketAddr::new(config.bind_tunnels, candidate);
                    match TcpListener::bind(bind_addr).await {
                        Ok(l) => {
                            let port = l.local_addr()?.port();
                            if port < config.min_port || port > config.max_port {
                                attempts += 1;
                                if attempts > 10000 {
                                    break;
                                }
                                continue;
                            }
                            // check if already allocated
                            {
                                let mut state = shared.lock().await;
                                if state.allocated_ports.contains_key(&port) {
                                    attempts += 1;
                                    continue;
                                }
                                state.allocated_ports.insert(port, ());
                            }
                            chosen = Some((port, l));
                            break;
                        }
                        Err(_) => {
                            attempts += 1;
                            if attempts > 10000 {
                                break;
                            }
                            continue;
                        }
                    }
                }
                if let Some((port, _listener)) = chosen {
                    // We have a listener but we drop it; run_client will create its own.
                    // Actually we have listener here, we could pass it to run_client. For simplicity, we drop and let run_client bind again (potential race but okay)
                    // To avoid race, we keep port reservation and drop listener
                    // But we already have listener; we drop it.
                    port
                } else {
                    let mut s = stream;
                    let _ = common::write_message_and_flush(&mut s, &Message::Error("no available port".to_string())).await;
                    return Err(anyhow!("no available port"));
                }
            }
        };

        run_client(stream, allocated, config, shared).await
    }

    async fn run_client(
        control_stream: TcpStream,
        remote_port: u16,
        config: ServerConfig,
        shared: Arc<Mutex<SharedState>>,
    ) -> Result<()> {
        // Now we have allocated port, we need to:
        // - send Hello(allocated) to client
        // - start tunnel listener on bind_tunnels:remote_port
        // - handle heartbeat and incoming public connections

        let mut control_stream = control_stream;
        common::write_message_and_flush(&mut control_stream, &Message::Hello(remote_port)).await?;
        info!(host = %config.bind_tunnels, port = remote_port, "new client");

        let tunnel_addr = SocketAddr::new(config.bind_tunnels, remote_port);
        let tunnel_listener = match TcpListener::bind(tunnel_addr).await {
            Ok(l) => l,
            Err(e) => {
                // cleanup
                {
                    let mut s = shared.lock().await;
                    s.allocated_ports.remove(&remote_port);
                }
                return Err(anyhow!("failed to bind tunnel: {}", e));
            }
        };

        // Split control stream into reader and writer halves protected by mutex for heartbeat and connection notifications
        let (control_read, control_write) = tokio::io::split(control_stream);
        let control_write = Arc::new(Mutex::new(control_write));
        let control_read = Arc::new(Mutex::new(control_read));

        // Heartbeat task
        let cw_clone = control_write.clone();
        let heartbeat_handle = tokio::spawn(async move {
            loop {
                tokio::time::sleep(HEARTBEAT_INTERVAL).await;
                let mut w = cw_clone.lock().await;
                if common::write_message(&mut *w, &Message::Heartbeat).await.is_err() {
                    break;
                }
                if w.flush().await.is_err() {
                    break;
                }
            }
        });

        // Tunnel accept loop
        loop {
            let (public_stream, public_addr) = match tunnel_listener.accept().await {
                Ok(x) => x,
                Err(e) => {
                    warn!("tunnel accept error: {}", e);
                    break;
                }
            };
            info!(%public_addr, port = remote_port, "new connection");
            let conn_id = Uuid::new_v4();
            {
                let mut state = shared.lock().await;
                state.pending.insert(conn_id, PendingConn { stream: public_stream, addr: public_addr });
            }

            // Send Connection message to client via control channel
            {
                let mut w = control_write.lock().await;
                if let Err(e) = common::write_message_and_flush(&mut *w, &Message::Connection(conn_id)).await {
                    warn!("failed to send Connection message: {}", e);
                    // cleanup pending
                    {
                        let mut state = shared.lock().await;
                        state.pending.remove(&conn_id);
                    }
                    break;
                }
            }
        }

        // Cleanup
        heartbeat_handle.abort();
        {
            let mut state = shared.lock().await;
            state.allocated_ports.remove(&remote_port);
        }

        Ok(())
    }

    async fn handle_accept(
        accept_stream: TcpStream,
        _addr: SocketAddr,
        conn_id: Uuid,
        shared: Arc<Mutex<SharedState>>,
    ) -> Result<()> {
        // Retrieve pending public connection
        let pending = {
            let mut state = shared.lock().await;
            state.pending.remove(&conn_id)
        };

        let pending = match pending {
            Some(p) => p,
            None => {
                // No such pending connection
                return Err(anyhow!("no pending connection for id {}", conn_id));
            }
        };

        info!(id = %conn_id, "forwarding connection");

        // Proxy between accept_stream (client) and pending.stream (public)
        let mut public_stream = pending.stream;
        let mut client_stream = accept_stream;

        // Bidirectional copy
        let (mut public_read, mut public_write) = public_stream.into_split();
        let (mut client_read, mut client_write) = client_stream.into_split();

        let p_to_c = tokio::io::copy(&mut public_read, &mut client_write);
        let c_to_p = tokio::io::copy(&mut client_read, &mut public_write);

        // Wait for either to complete
        tokio::select! {
            res = p_to_c => {
                if let Err(e) = res {
                    warn!("public->client copy error: {}", e);
                }
            },
            res = c_to_p => {
                if let Err(e) = res {
                    warn!("client->public copy error: {}", e);
                }
            },
        }

        Ok(())
    }
}

mod client {
    use super::auth;
