    const CONTROL_PORT: u16 = 7835;

    pub struct Client {
        local_host: String,
        local_port: u16,
        to: String,
        remote_port: u16,
        secret: Option<String>,
    }

    impl Client {
        pub fn new(local_host: String, local_port: u16, to: String, remote_port: u16, secret: Option<String>) -> Self {
            Self {
                local_host,
                local_port,
                to,
                remote_port,
                secret,
            }
        }

        pub async fn run(self) -> Result<()> {
            // Resolve control address: to is expected to be host without port, we append :7835.
            // But if to already contains : it would become invalid; earlier behavior shows it tries to connect to "host:port:7835" and fails with "failed to lookup address information".
            // So we should mimic naive appending: format!("{}:{}", to, CONTROL_PORT)
            // However, if to already includes port? We still append.
            let control_addr_str = format!("{}:{}", self.to, CONTROL_PORT);
            let control_addr = control_addr_str.clone();

            let stream = TcpStream::connect(&control_addr_str).await.map_err(|e| {
                anyhow!("could not connect to {}:{}", self.to, CONTROL_PORT)
                    .context(e)
            })?;

            // Handshake
            let (mut read_half, mut write_half) = tokio::io::split(stream);

            // If secret provided, we expect Challenge first
            // If no secret, we send Hello first

            let remote_port_allocated: u16;

            if let Some(secret) = self.secret.clone() {
                // Wait for Challenge
                let msg = match tokio::time::timeout(
                    std::time::Duration::from_secs(3),
                    common::read_message(&mut read_half)
                ).await {
                    Ok(res) => res?,
                    Err(_) => {
                        return Err(anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"));
                    }
                };

                let challenge = match msg {
                    Some(Message::Challenge(c)) => c,
                    Some(Message::Hello(_)) => {
                        // Server sent Hello but we expected Challenge -> no secret required on server but we have secret
                        return Err(anyhow!("expected authentication challenge, but no secret was required"));
                    }
                    Some(Message::Error(e)) => {
                        // Server sent error? Could be? For secret required case, server wouldn't send Hello.
                        return Err(anyhow!("server error: {}", e));
                    }
                    other => {
                        return Err(anyhow!("unexpected message: {:?}", other));
                    }
                };

                // Send Authenticate
                let auth_token = auth::answer(&challenge, &secret);
                common::write_message_and_flush(&mut write_half, &Message::Authenticate(auth_token)).await?;
                // Send Hello
                common::write_message_and_flush(&mut write_half, &Message::Hello(self.remote_port)).await?;

                // Wait for response: should be Hello or Error
                let resp = match tokio::time::timeout(
                    std::time::Duration::from_secs(3),
                    common::read_message(&mut read_half)
                ).await {
                    Ok(r) => r?,
                    Err(_) => {
                        return Err(anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"));
                    }
                };

                match resp {
                    Some(Message::Hello(port)) => {
                        remote_port_allocated = port;
                    }
                    Some(Message::Error(e)) => {
                        return Err(anyhow!("server error: {}", e));
                    }
                    Some(other) => {
                        return Err(anyhow!("unexpected message: {:?}", other));
                    }
                    None => return Err(anyhow!("connection closed")),
                }

            } else {
                // No secret: send Hello first
                common::write_message_and_flush(&mut write_half, &Message::Hello(self.remote_port)).await?;

                // Wait for response: Hello or Challenge or Error
                let resp = match tokio::time::timeout(
                    std::time::Duration::from_secs(3),
                    common::read_message(&mut read_half)
                ).await {
                    Ok(r) => r?,
                    Err(_) => {
                        return Err(anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"));
                    }
                };

                match resp {
                    Some(Message::Hello(port)) => {
                        remote_port_allocated = port;
                    }
                    Some(Message::Challenge(_)) => {
                        // Server requires auth but we didn't provide secret
                        return Err(anyhow!("server requires authentication, but no client secret was provided"));
                    }
                    Some(Message::Error(e)) => {
                        return Err(anyhow!("server error: {}", e));
                    }
                    Some(other) => {
                        return Err(anyhow!("unexpected message: {:?}", other));
                    }
                    None => return Err(anyhow!("connection closed")),
                }
            }

            info!(remote_port = remote_port_allocated, "connected to server");
            // The listening at message: format exactly like original: "listening at {}:{}"
            // The host part: It should be the remote host? In earlier logs, second part was "listening at 127.0.0.1:13090" where 127.0.0.1 is the --to host? Or is it the tunnel bind addr?
            // In original, for server with bind-addr 127.0.0.2 and client --to 127.0.0.1 (MITM), the log after successful connect said listening at 127.0.0.1:13090 even though server tunnel was on 127.0.0.2? Wait earlier MITM test: server bind 127.0.0.2, client to 127.0.0.1 (MITM). The MITM forwards to 127.0.0.2, but client logs "listening at 127.0.0.1:13090". So the second host is the "to" argument, not the actual tunnel bind addr? Actually in first MITM test with server on 127.0.0.2, client to 127.0.0.1, after connect client log was "listening at 127.0.0.1:13090" – that's the to host (127.0.0.1), not the server's bind_tunnels (127.0.0.2). So original bore logs listening at {to}:{remote_port}?
            // But in second test without MITM, server bind 0.0.0.0, client to 127.0.0.1, log was "listening at 127.0.0.1:13470" – again to host = 127.0.0.1.
            // For server bind 127.0.0.2 and client to 127.0.0.2 directly (no MITM), log was "listening at 127.0.0.2:17185" – to host = 127.0.0.2.
            // For earlier test with server bind 127.0.0.1, client to 127.0.0.1, bind_tunnels 127.0.0.2, log was "listening at 127.0.0.1:6256" – to host again, not bind_tunnels.
            // Actually check: earlier test bind-addr 127.0.0.1 bind-tunnels 127.0.0.2, client to 127.0.0.1 – log said listening at 127.0.0.1:6256, but tunnel actually listens on 127.0.0.2:6256. So log says 127.0.0.1:6256 even though tunnel is on 127.0.0.2.
            // So log's IP is the --to argument (or its resolved? But it's the string? In log it shows IP). Let's see: if --to is "localhost", what would log show? We need to test.

            // Anyway, we will log listening at <to>:<remote_port> where <to> is the original "to" string? But if to is a hostname, we should probably show as given? Original shows IP? In case to = 127.0.0.1, it shows 127.0.0.1. If to is hostname, it might show hostname? Or resolved?

            // In earlier simple tests without bind-tunnels, when server bind_addr 127.0.0.1, tunnel also on 127.0.0.1, so listening at 127.0.0.1 matches both to and bind.

            // To reproduce, we will log as "listening at {}:{}" where first is the `to` value (as provided) and second is remote_port. But we should ensure it matches original: If to is a domain, it might show domain? Let's assume.

            // However original code logs remote_port as allocated and also logs listening at <remote_host>:<remote_port> where remote_host is the server's advertised host? Might be the host field from server's Hello response? Actually server sends Hello(port) only, not host. So client must know host from its own perspective (the server address). Possibly it uses the resolved IP of `to`? Or uses the server's bind_addr? But from tests, it used `to` string.

            // Let's check server's new client log: "new client host=127.0.0.2 port=..." where host is bind_tunnels, not to. Client's listening log uses to.

            // So we will log listening at {to}:{port}

            info!("listening at {}:{}", self.to, remote_port_allocated);

            // Now we need to handle connections from server: it will send Connection(uuid) messages over control channel, and we need to for each, open a new connection to server's control port, authenticate if needed, send Accept(uuid), then proxy between that new connection and local service.

            // Recombine read_half and write_half into a single stream? Actually we already split; we need to keep reading from control channel for Connection messages.

            // The control stream is still open; we will continue reading from read_half.

            // For each Connection, spawn a task to handle proxy.

            // We need also to keep sending heartbeats? Client doesn't send heartbeat, it receives them. So we just read and ignore Heartbeat.

            // Loop
            loop {
                let msg = common::read_message(&mut read_half).await?;
                match msg {
                    Some(Message::Connection(conn_id)) => {
                        let to_clone = self.to.clone();
                        let secret_clone = self.secret.clone();
                        let local_host_clone = self.local_host.clone();
                        let local_port = self.local_port;
                        info!(id = %conn_id, "new connection");
                        tokio::spawn(async move {
                            if let Err(e) = handle_proxy_connection(to_clone, secret_clone, local_host_clone, local_port, conn_id).await {
                                // Log?
                                tracing::warn!("proxy connection failed: {}", e);
                            }
                        });
                    }
                    Some(Message::Heartbeat) => {
                        // ignore
                    }
                    Some(Message::Error(e)) => {
                        // Server error? just log and exit?
                        return Err(anyhow!("server error: {}", e));
                    }
                    Some(other) => {
                        tracing::warn!("unexpected message from server: {:?}", other);
                    }
                    None => {
                        // connection closed
                        break;
                    }
                }
            }

            Ok(())
        }
    }

    #[instrument(skip(to, secret, local_host))]
    async fn handle_proxy_connection(
        to: String,
        secret: Option<String>,
        local_host: String,
        local_port: u16,
        conn_id: Uuid,
    ) -> anyhow::Result<()> {
        // Connect to control port again
        let control_addr_str = format!("{}:{}", to, CONTROL_PORT);
        let mut stream = TcpStream::connect(&control_addr_str).await.context("failed to connect for proxy")?;

        // Auth if needed
        if let Some(secret_val) = secret.clone() {
            // Expect Challenge
            let challenge_msg = common::read_message(&mut stream).await?;
            let challenge = match challenge_msg {
                Some(Message::Challenge(c)) => c,
                Some(Message::Error(e)) => return Err(anyhow!("server error: {}", e)),
                other => return Err(anyhow!("expected Challenge, got {:?}", other)),
            };
            let token = auth::answer(&challenge, &secret_val);
            common::write_message_and_flush(&mut stream, &Message::Authenticate(token)).await?;
        }

        // Send Accept
        common::write_message_and_flush(&mut stream, &Message::Accept(conn_id)).await?;

        // Now proxy: connect to local host:port, then copy
        let local_addr = format!("{}:{}", local_host, local_port);
        let mut local_stream = TcpStream::connect(&local_addr).await.context("failed to connect to local")?;

        // Bidirectional copy
        let (mut local_read, mut local_write) = local_stream.into_split();
        let (mut remote_read, mut remote_write) = stream.into_split();

        let l_to_r = tokio::io::copy(&mut local_read, &mut remote_write);
        let r_to_l = tokio::io::copy(&mut remote_read, &mut local_write);

        tokio::select! {
            res = l_to_r => {
                if let Err(e) = res {
                    tracing::warn!("local->remote copy error: {}", e);
                }
            },
            res = r_to_l => {
                if let Err(e) = res {
                    tracing::warn!("remote->local copy error: {}", e);
                }
            },
        }

        tracing::info!(id = %conn_id, "connection exited");
        Ok(())
    }
}

