                    let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_str.clone())).await;
                    warn!(err = %err_str, "server handshake failed");
                    return Err(anyhow!(err_str));
                }
                Some(other) => {
                    let err_str = format!("unexpected message: {:?}", other);
                    let _ = common::write_message_and_flush(&mut stream, &Message::Error("invalid secret".to_string())).await;
                    warn!(err = %err_str, "server handshake failed");
                    return Err(anyhow!(err_str));
                }
                None => {
