                let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_str.clone())).await;
                warn!(err = %err_str, "server handshake failed");
                return Err(anyhow!(err_str));
            }

            // Auth ok, now read next message (should be Hello or Accept)
            let second_msg = match read_with_timeout(&mut stream).await {
                Ok(m) => m,
                Err(e) => {
                    let err_str = e.to_string();
                    let _ = common::write_message_and_flush(&mut stream, &Message::Error(err_str.clone())).await;
                    warn!(err = %err_str, "server handshake failed");
                    return Err(anyhow!(err_str));
                }
            };

            match second_msg {
                Some(Message::Hello(port)) => {
                    // New client
                    handle_new_client(stream, addr, port, config, shared).await?;
                }
                Some(Message::Accept(uuid)) => {
                    // Proxy connection
                    handle_accept(stream, addr, uuid, shared).await?;
                }
                Some(other) => {
                    warn!(?other, "unexpected message after auth");
                    return Err(anyhow!("unexpected message"));
                }
                None => return Err(anyhow!("connection closed")),
