            // But if to already contains : it would become invalid; earlier behavior shows it tries to connect to "host:port:7835" and fails with "failed to lookup address information".
            // So we should mimic naive appending: format!("{}:{}", to, CONTROL_PORT)
            // However, if to already includes port? We still append.
            let control_addr_str = format!("{}:{}", self.to, CONTROL_PORT);
            let control_addr = control_addr_str.clone();

            let stream = TcpStream::connect(&control_addr_str).await.map_err(|e| {
                anyhow!("could not connect to {}:{}", self.to, CONTROL_PORT)
                    .context(e)
            })?;

            // Handshake
            let (mut read_half, mut write_half) = tokio::io::split(stream);

