        common::write_message_and_flush(&mut stream, &Message::Accept(conn_id)).await?;

        // Now proxy: connect to local host:port, then copy
        let local_addr = format!("{}:{}", local_host, local_port);
        let mut local_stream = TcpStream::connect(&local_addr).await.context("failed to connect to local")?;

        // Bidirectional copy
        let (mut local_read, mut local_write) = local_stream.into_split();
        let (mut remote_read, mut remote_write) = stream.into_split();

        let l_to_r = tokio::io::copy(&mut local_read, &mut remote_write);
        let r_to_l = tokio::io::copy(&mut remote_read, &mut local_write);

        tokio::select! {
            res = l_to_r => {
                if let Err(e) = res {
                    tracing::warn!("local->remote copy error: {}", e);
                }
            },
            res = r_to_l => {
                if let Err(e) = res {
                    tracing::warn!("remote->local copy error: {}", e);
                }
            },
        }

        tracing::info!(id = %conn_id, "connection exited");
        Ok(())
