fn handle_accept(mut accept_stream: TcpStream, addr: SocketAddr, conn_id: Uuid, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    let pending = {
        let mut state = shared.lock().unwrap();
        state.pending.remove(&conn_id)
    };
    let pending = match pending {
        Some(p) => p,
        None => return Err(anyhow!("no pending")),
    };
    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m forwarding connection \x1b[3mid\x1b[0m\x1b[2m=\x1b[0m{}", addr, conn_id);
    let mut public_stream = pending.stream;
    let mut client_stream = accept_stream;

    // proxy
    let mut public_read = public_stream.try_clone()?;
    let mut public_write = public_stream;
    let mut client_read = client_stream.try_clone()?;
    let mut client_write = client_stream;

    // Use two threads for bidirectional copy
    let handle1 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match public_read.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if client_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });
    let handle2 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match client_read.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if public_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });
    let _ = handle1.join();
    let _ = handle2.join();

    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);

    Ok(())
}

