mod common {
    use super::protocol::Message;
    use anyhow::Result;
    use std::io::{Read, Write};
    use std::net::TcpStream;

    pub fn read_message(stream: &mut TcpStream) -> Result<Option<Message>> {
        let mut buf = Vec::new();
        let mut byte = [0u8; 1];
        loop {
            let n = stream.read(&mut byte)?;
            if n == 0 {
                if buf.is_empty() {
                    return Ok(None);
                } else {
                    return Err(anyhow::anyhow!("connection closed before null byte"));
                }
            }
            if byte[0] == 0 {
                break;
            }
            buf.push(byte[0]);
        }
        if buf.is_empty() {
            return Ok(None);
        }
        let msg: Message = serde_json::from_slice(&buf)?;
        Ok(Some(msg))
    }

    pub fn write_message(stream: &mut TcpStream, msg: &Message) -> Result<()> {
        let json = serde_json::to_string(msg)?;
        stream.write_all(json.as_bytes())?;
        stream.write_all(&[0])?;
        Ok(())
    }

    pub fn write_message_and_flush(stream: &mut TcpStream, msg: &Message) -> Result<()> {
        write_message(stream, msg)?;
        stream.flush()?;
        Ok(())
    }

    pub fn set_read_timeout(stream: &TcpStream, dur: Duration) -> Result<()> {
        stream.set_read_timeout(Some(dur))?;
        Ok(())
    }
}

