                        }
                    }
                    other => {
                        if other.starts_with('-') {
                            eprintln!("error: unexpected argument '{}' found", other);
                            eprintln!();
                            eprintln!("Usage: executable server [OPTIONS]");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        } else {
                            eprintln!("error: unexpected argument '{}' found", other);
                            eprintln!();
                            eprintln!("Usage: executable server [OPTIONS]");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                    }
                }
                i += 1;
            }

            // validate port range
            if min_port > max_port {
                eprintln!("error: port range is empty");
                eprintln!();
                eprintln!("Usage: bore-cli <COMMAND>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }

            Ok(Cli {
                command: Commands::Server(ServerArgs {
                    min_port,
                    max_port,
                    secret,
                    bind_addr,
                    bind_tunnels,
                }),
            })
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", sub);
            eprintln!();
            eprintln!("Usage: executable <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

mod auth {
    use super::*;
    use sha2::{Digest, Sha256};
    use hmac::{Hmac, Mac};
    use uuid::Uuid;
    type HmacSha256 = Hmac<Sha256>;

    pub fn answer(challenge: &Uuid, secret: &str) -> String {
        let hashed_secret = Sha256::digest(secret.as_bytes());
        let mut mac = HmacSha256::new_from_slice(&hashed_secret).expect("HMAC can take key of any size");
        mac.update(challenge.as_bytes());
        let result = mac.finalize().into_bytes();
        hex::encode(result)
    }
}

