fn handle_connection_inner(mut stream: TcpStream, addr: SocketAddr, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    // Log incoming connection
    // For server
    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m incoming connection", addr);

    stream.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;

    if let Some(secret_value) = config.secret.clone() {
        // Send challenge
        let challenge = Uuid::new_v4();
        write_message_and_flush(&mut stream, &Message::Challenge(challenge))?;

        // Wait for first message
        let first_msg = match read_message(&mut stream) {
            Ok(m) => m,
            Err(e) => {
                let err_str = if e.to_string().contains("timed out") || e.to_string().contains("WouldBlock") || e.to_string().contains("TimedOut") || e.to_string().contains("timed out") {
                    "timed out waiting for initial message".to_string()
                } else {
                    e.to_string()
                };
                // If timeout, error is "timed out waiting for initial message"
                // We need to detect if it's timeout error: std read timeout returns WouldBlock? Actually it returns TimedOut? Let's handle.
                let actual_err = if err_str.contains("timed out") || format!("{:?}", e).contains("TimedOut") || e.to_string().contains("timed out") {
                    "timed out waiting for initial message".to_string()
                } else {
                    err_str.clone()
                };
                // Send Error
                let _ = write_message_and_flush(&mut stream, &Message::Error(actual_err.clone()));
                eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", addr, actual_err);
                eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);
                return Err(anyhow!(actual_err));
            }
        };

        match first_msg {
            Some(Message::Authenticate(token)) => {
                // verify
                let expected = auth::answer(&challenge, &secret_value);
                if expected != token {
                    let err_str = "invalid secret".to_string();
                    let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", addr, err_str);
                    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);
                    return Err(anyhow!(err_str));
                }
                // auth ok, now read next message
                let second_msg = match read_message(&mut stream) {
                    Ok(m) => m,
                    Err(e) => {
                        let err_str = "timed out waiting for initial message".to_string();
                        let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                        eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", addr, err_str);
                        eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);
                        return Err(anyhow!(err_str));
                    }
                };
                match second_msg {
                    Some(Message::Hello(port)) => {
                        // new client
                        if let Err(e) = handle_new_client(stream, addr, port, config, shared) {
                            // handle_new_client already sends error messages if needed
                            eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);
                            return Err(e);
                        }
                    }
                    Some(Message::Accept(uuid)) => {
                        handle_accept(stream, addr, uuid, shared)?;
                    }
                    _ => {
                        return Err(anyhow!("unexpected message"));
                    }
                }
            }
            Some(Message::Hello(_)) => {
                let err_str = "server requires secret, but no secret was provided".to_string();
                let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", addr, err_str);
                eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);
                return Err(anyhow!(err_str));
            }
            _ => {
                return Err(anyhow!("unexpected"));
            }
        }
    } else {
        // No secret
        let first_msg = match read_message(&mut stream) {
            Ok(m) => m,
            Err(e) => {
                let err_str = e.to_string();
                // Check if timeout
                let is_timeout = err_str.contains("timed out") || format!("{:?}", e).contains("TimedOut") || e.to_string().contains("WouldBlock") || err_str.contains("timed out waiting");
                if is_timeout {
                    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited with error \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", addr, "timed out waiting for initial message");
                    return Err(anyhow!("timed out waiting for initial message"));
                } else {
                    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited with error \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", addr, err_str);
                    return Err(anyhow!(err_str));
                }
            }
        };
        match first_msg {
            Some(Message::Hello(port)) => {
                if let Err(e) = handle_new_client(stream, addr, port, config, shared) {
                    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", addr);
                    return Err(e);
                }
            }
            Some(Message::Accept(uuid)) => {
                handle_accept(stream, addr, uuid, shared)?;
            }
            Some(other) => {
                eprintln!("unexpected message: {:?}", other);
                return Err(anyhow!("unexpected"));
            }
            None => return Err(anyhow!("closed")),
        }
    }
    Ok(())
}

fn handle_new_client(mut stream: TcpStream, addr: SocketAddr, requested_port: u16, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    // Allocate port
    let allocated = {
        if requested_port != 0 {
            if requested_port < config.min_port || requested_port > config.max_port {
                let _ = write_message_and_flush(&mut stream, &Message::Error("client port number not in allowed range".to_string()));
                return Err(anyhow!("client port number not in allowed range"));
            }
            {
                let state = shared.lock().unwrap();
                if state.allocated_ports.contains_key(&requested_port) {
                    drop(state);
                    let _ = write_message_and_flush(&mut stream, &Message::Error("port already in use".to_string()));
                    return Err(anyhow!("port already in use"));
                }
            }
            // Try bind
            let bind_addr = SocketAddr::new(config.bind_tunnels, requested_port);
            match TcpListener::bind(bind_addr) {
                Ok(l) => {
                    drop(l);
                    let mut state = shared.lock().unwrap();
                    state.allocated_ports.insert(requested_port, ());
                    requested_port
                }
                Err(_) => {
                    let _ = write_message_and_flush(&mut stream, &Message::Error("port already in use".to_string()));
                    return Err(anyhow!("port already in use"));
                }
            }
        } else {
            // random
            let mut attempts = 0;
            let mut chosen = None;
            loop {
                let candidate = if config.min_port == 0 && config.max_port == 65535 {
                    0
                } else {
                    if attempts < (config.max_port - config.min_port + 1) as usize {
                        config.min_port + (attempts as u16 % (config.max_port - config.min_port + 1))
                    } else {
                        0
                    }
                };
                if candidate != 0 {
                    let state = shared.lock().unwrap();
                    if state.allocated_ports.contains_key(&candidate) {
                        attempts += 1;
                        if attempts > 10000 {
                            break;
                        }
                        continue;
                    }
                }
                let bind_addr = SocketAddr::new(config.bind_tunnels, candidate);
                match TcpListener::bind(bind_addr) {
                    Ok(l) => {
                        let port = l.local_addr()?.port();
                        if port < config.min_port || port > config.max_port {
                            attempts += 1;
                            if attempts > 10000 {
                                break;
                            }
                            continue;
                        }
                        {
                            let mut state = shared.lock().unwrap();
                            if state.allocated_ports.contains_key(&port) {
                                attempts += 1;
                                continue;
                            }
                            state.allocated_ports.insert(port, ());
                        }
                        chosen = Some(port);
                        break;
                    }
                    Err(_) => {
                        attempts += 1;
                        if attempts > 10000 {
                            break;
                        }
                        continue;
                    }
                }
            }
            if let Some(port) = chosen {
                port
            } else {
                let _ = write_message_and_flush(&mut stream, &Message::Error("no available port".to_string()));
                return Err(anyhow!("no available port"));
            }
        }
    };

    run_client(stream, addr, allocated, config, shared)
}

fn run_client(control_stream: TcpStream, control_addr: SocketAddr, remote_port: u16, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    let mut control_stream = control_stream;
    write_message_and_flush(&mut control_stream, &Message::Hello(remote_port))?;
    eprintln!("\x1b[2m2026-09-08T00:00:00.000000Z\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m new client \x1b[3mhost\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", control_addr, config.bind_tunnels, remote_port);

    let tunnel_addr = SocketAddr::new(config.bind_tunnels, remote_port);
    let tunnel_listener = TcpListener::bind(tunnel_addr)?;

    // For heartbeat, we need to send periodically in a thread
    let mut control_write = control_stream.try_clone()?;
    let heartbeat_handle = std::thread::spawn(move || {
        loop {
            std::thread::sleep(HEARTBEAT_INTERVAL);
            if write_message_and_flush(&mut control_write, &Message::Heartbeat).is_err() {
                break;
            }
        }
    });

    loop {
        let (public_stream, public_addr) = match tunnel_listener.accept() {
            Ok(x) => x,
