mod hmac {
    // minimal HMAC implementation using sha2
    use sha2::{Sha256, Digest};
    use sha2::digest::FixedOutput;

    pub struct Hmac<S> {
        inner: S,
        outer: S,
        // We need to store key?
    }

    impl<S> Hmac<S>
    where
        S: Digest + Clone,
    {
        pub fn new_from_slice(key: &[u8]) -> Result<Self, &'static str> {
            // HMAC key handling: if key longer than block size, hash it
            // Block size for SHA256 is 64
            let block_size = 64;
            let mut key_block = vec![0u8; block_size];
            if key.len() > block_size {
                let mut hasher = S::new();
                hasher.update(key);
                let hashed = hasher.finalize_fixed();
                key_block[..hashed.len()].copy_from_slice(&hashed);
            } else {
                key_block[..key.len()].copy_from_slice(key);
            }

            let mut ipad = vec![0x36u8; block_size];
            let mut opad = vec![0x5cu8; block_size];
            for i in 0..block_size {
                ipad[i] ^= key_block[i];
                opad[i] ^= key_block[i];
            }

            let mut inner = S::new();
            inner.update(&ipad);
            let mut outer = S::new();
            outer.update(&opad);

            Ok(Self { inner, outer })
        }

        pub fn update(&mut self, data: &[u8]) {
            self.inner.update(data);
        }

        pub fn finalize(self) -> GenericArray {
            let inner_result = self.inner.finalize_fixed();
            let mut outer = self.outer;
            outer.update(&inner_result);
            let outer_result = outer.finalize_fixed();
            GenericArray(outer_result.to_vec())
        }
    }

    pub struct GenericArray(Vec<u8>);

    impl GenericArray {
        pub fn to_vec(self) -> Vec<u8> {
            self.0
        }
    }

    impl std::ops::Deref for GenericArray {
        type Target = [u8];
        fn deref(&self) -> &Self::Target {
            &self.0
        }
    }

    pub trait Mac {
        fn new_from_slice(key: &[u8]) -> Result<Self, &'static str> where Self: Sized;
        fn update(&mut self, data: &[u8]);
        fn finalize(self) -> GenericArray;
    }

    impl Mac for Hmac<Sha256> {
        fn new_from_slice(key: &[u8]) -> Result<Self, &'static str> where Self: Sized {
            Hmac::new_from_slice(key)
        }
        fn update(&mut self, data: &[u8]) {
            Hmac::update(self, data)
        }
        fn finalize(self) -> GenericArray {
            Hmac::finalize(self)
        }
    }
}
