    println!("  -s, --secret <SECRET>              Optional secret for authentication [env: BORE_SECRET]");
    println!("      --bind-addr <BIND_ADDR>        IP address to bind to, clients must reach this [default: 0.0.0.0]");
    println!("      --bind-tunnels <BIND_TUNNELS>  IP address where tunnels will listen on, defaults to --bind-addr");
    println!("  -h, --help                         Print help");
}

fn parse_args() -> Result<Cli> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        print_help();
        std::process::exit(0);
    }
    let sub = args[1].as_str();
    match sub {
        "-h" | "--help" | "help" => {
            if args.len() >= 3 {
                match args[2].as_str() {
                    "local" => print_local_help(),
                    "server" => print_server_help(),
                    _ => print_help(),
                }
            } else {
                print_help();
            }
            std::process::exit(0);
        }
        "-V" | "--version" => {
            println!("bore-cli 0.6.0");
            std::process::exit(0);
        }
        "local" => {
            let mut local_port: Option<u16> = None;
            let mut local_host = "localhost".to_string();
            let mut to: Option<String> = None;
            let mut port: u16 = 0;
            let mut secret: Option<String> = None;

            if let Ok(v) = std::env::var("BORE_LOCAL_PORT") {
                if let Ok(p) = v.parse::<u16>() {
                    local_port = Some(p);
                } else {
                    eprintln!("error: invalid value '{}' for '<LOCAL_PORT>': invalid digit found in string", v);
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
            if let Ok(v) = std::env::var("BORE_SERVER") {
                to = Some(v);
            }
            if let Ok(v) = std::env::var("BORE_SECRET") {
                secret = Some(v);
            }

            let mut i = 2;
            while i < args.len() {
                let a = args[i].as_str();
                match a {
                    "-h" | "--help" => {
                        print_local_help();
                        std::process::exit(0);
                    }
                    "-l" | "--local-host" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--local-host <HOST>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        local_host = args[i].clone();
                    }
                    s if s.starts_with("--local-host=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        local_host = v.to_string();
                    }
                    "-t" | "--to" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--to <TO>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        to = Some(args[i].clone());
                    }
                    s if s.starts_with("--to=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        to = Some(v.to_string());
                    }
                    "-p" | "--port" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--port <PORT>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        match args[i].parse::<u16>() {
                            Ok(p) => port = p,
                            Err(_) => {
                                if let Ok(num) = args[i].parse::<i32>() {
                                    eprintln!("error: invalid value '{}' for '--port <PORT>': {} is not in 0..=65535", args[i], num);
                                } else {
                                    eprintln!("error: invalid value '{}' for '--port <PORT>': invalid digit found in string", args[i]);
                                }
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    s if s.starts_with("--port=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        match v.parse::<u16>() {
                            Ok(p) => port = p,
                            Err(_) => {
                                if let Ok(num) = v.parse::<i32>() {
                                    eprintln!("error: invalid value '{}' for '--port <PORT>': {} is not in 0..=65535", v, num);
                                } else {
                                    eprintln!("error: invalid value '{}' for '--port <PORT>': invalid digit found in string", v);
                                }
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    "-s" | "--secret" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--secret <SECRET>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        secret = Some(args[i].clone());
                    }
                    s if s.starts_with("--secret=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        secret = Some(v.to_string());
                    }
                    _ => {
                        if a.starts_with('-') {
                            eprintln!("error: unexpected argument '{}' found", a);
                            eprintln!();
                            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
                            eprintln!();
                            eprintln!("Usage: executable local [OPTIONS] --to <TO> <LOCAL_PORT>");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        } else {
                            if local_port.is_some() {
                                eprintln!("error: unexpected argument '{}' found", a);
                                eprintln!();
                                eprintln!("Usage: executable local [OPTIONS] --to <TO> <LOCAL_PORT>");
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                            match a.parse::<u16>() {
                                Ok(p) => local_port = Some(p),
                                Err(_) => {
                                    eprintln!("error: invalid value '{}' for '<LOCAL_PORT>': invalid digit found in string", a);
                                    eprintln!();
                                    eprintln!("For more information, try '--help'.");
                                    std::process::exit(2);
                                }
                            }
                        }
                    }
                }
                i += 1;
            }

            if to.is_none() {
                eprintln!("error: the following required arguments were not provided:");
                eprintln!("  --to <TO>");
                if local_port.is_none() {
                    eprintln!("  <LOCAL_PORT>");
                }
                eprintln!();
                eprintln!("Usage: executable local --to <TO> <LOCAL_PORT>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            if local_port.is_none() {
                eprintln!("error: the following required arguments were not provided:");
                eprintln!("  <LOCAL_PORT>");
                eprintln!();
                eprintln!("Usage: executable local --to <TO> <LOCAL_PORT>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }

            Ok(Cli {
                command: Commands::Local(LocalArgs {
                    local_port: local_port.unwrap(),
                    local_host,
                    to: to.unwrap(),
                    port,
                    secret,
                }),
            })
        }
        "server" => {
            let mut min_port: u16 = 1024;
            let mut max_port: u16 = 65535;
            let mut secret: Option<String> = None;
            let mut bind_addr: IpAddr = "0.0.0.0".parse().unwrap();
            let mut bind_tunnels: Option<IpAddr> = None;

            if let Ok(v) = std::env::var("BORE_MIN_PORT") {
                match v.parse::<u16>() {
                    Ok(p) => min_port = p,
                    Err(_) => {
                        eprintln!("error: invalid value '{}' for '--min-port <MIN_PORT>': invalid digit found in string", v);
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        std::process::exit(2);
                    }
                }
            }
            if let Ok(v) = std::env::var("BORE_MAX_PORT") {
                match v.parse::<u16>() {
                    Ok(p) => max_port = p,
                    Err(_) => {
                        eprintln!("error: invalid value '{}' for '--max-port <MAX_PORT>': invalid digit found in string", v);
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        std::process::exit(2);
                    }
                }
            }
            if let Ok(v) = std::env::var("BORE_SECRET") {
                secret = Some(v);
            }

            let mut i = 2;
            while i < args.len() {
                let a = args[i].as_str();
                match a {
                    "-h" | "--help" => {
                        print_server_help();
                        std::process::exit(0);
                    }
                    "--min-port" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--min-port <MIN_PORT>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        let v = &args[i];
                        match v.parse::<u16>() {
                            Ok(p) => min_port = p,
                            Err(_) => {
                                if let Ok(num) = v.parse::<i32>() {
                                    eprintln!("error: invalid value '{}' for '--min-port <MIN_PORT>': {} is not in 0..=65535", v, num);
                                } else {
                                    eprintln!("error: invalid value '{}' for '--min-port <MIN_PORT>': invalid digit found in string", v);
                                }
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    s if s.starts_with("--min-port=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        match v.parse::<u16>() {
                            Ok(p) => min_port = p,
                            Err(_) => {
                                if let Ok(num) = v.parse::<i32>() {
                                    eprintln!("error: invalid value '{}' for '--min-port <MIN_PORT>': {} is not in 0..=65535", v, num);
                                } else {
                                    eprintln!("error: invalid value '{}' for '--min-port <MIN_PORT>': invalid digit found in string", v);
                                }
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    "--max-port" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--max-port <MAX_PORT>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        let v = &args[i];
                        match v.parse::<u16>() {
                            Ok(p) => max_port = p,
                            Err(_) => {
                                if let Ok(num) = v.parse::<i32>() {
                                    eprintln!("error: invalid value '{}' for '--max-port <MAX_PORT>': {} is not in 0..=65535", v, num);
                                } else {
                                    eprintln!("error: invalid value '{}' for '--max-port <MAX_PORT>': invalid digit found in string", v);
                                }
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    s if s.starts_with("--max-port=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        match v.parse::<u16>() {
                            Ok(p) => max_port = p,
                            Err(_) => {
                                if let Ok(num) = v.parse::<i32>() {
                                    eprintln!("error: invalid value '{}' for '--max-port <MAX_PORT>': {} is not in 0..=65535", v, num);
                                } else {
                                    eprintln!("error: invalid value '{}' for '--max-port <MAX_PORT>': invalid digit found in string", v);
                                }
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    "-s" | "--secret" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--secret <SECRET>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        secret = Some(args[i].clone());
                    }
                    s if s.starts_with("--secret=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        secret = Some(v.to_string());
                    }
                    "--bind-addr" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--bind-addr <BIND_ADDR>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        match args[i].parse::<IpAddr>() {
                            Ok(ip) => bind_addr = ip,
                            Err(_) => {
                                eprintln!("error: invalid value '{}' for '--bind-addr <BIND_ADDR>': invalid IP address syntax", args[i]);
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    s if s.starts_with("--bind-addr=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        match v.parse::<IpAddr>() {
                            Ok(ip) => bind_addr = ip,
                            Err(_) => {
                                eprintln!("error: invalid value '{}' for '--bind-addr <BIND_ADDR>': invalid IP address syntax", v);
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    "--bind-tunnels" => {
                        i += 1;
                        if i >= args.len() {
                            eprintln!("error: a value is required for '--bind-tunnels <BIND_TUNNELS>' but none was supplied");
                            eprintln!();
                            eprintln!("For more information, try '--help'.");
                            std::process::exit(2);
                        }
                        match args[i].parse::<IpAddr>() {
                            Ok(ip) => bind_tunnels = Some(ip),
                            Err(_) => {
                                eprintln!("error: invalid value '{}' for '--bind-tunnels <BIND_TUNNELS>': invalid IP address syntax", args[i]);
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    s if s.starts_with("--bind-tunnels=") => {
                        let v = s.splitn(2, '=').nth(1).unwrap();
                        match v.parse::<IpAddr>() {
                            Ok(ip) => bind_tunnels = Some(ip),
                            Err(_) => {
                                eprintln!("error: invalid value '{}' for '--bind-tunnels <BIND_TUNNELS>': invalid IP address syntax", v);
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    other => {
                        eprintln!("error: unexpected argument '{}' found", other);
                        eprintln!();
                        eprintln!("Usage: executable server [OPTIONS]");
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        std::process::exit(2);
                    }
                }
                i += 1;
            }

            if min_port > max_port {
                eprintln!("error: port range is empty");
                eprintln!();
                eprintln!("Usage: bore-cli <COMMAND>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }

            Ok(Cli {
                command: Commands::Server(ServerArgs {
                    min_port,
                    max_port,
                    secret,
                    bind_addr,
                    bind_tunnels,
                }),
            })
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", sub);
            eprintln!();
            eprintln!("Usage: executable <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

struct PendingConn {
    stream: TcpStream,
    addr: SocketAddr,
}

struct SharedState {
    allocated_ports: HashMap<u16, ()>,
    pending: HashMap<Uuid, PendingConn>,
}

#[derive(Clone)]
struct ServerConfig {
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: IpAddr,
    bind_tunnels: IpAddr,
}

fn log_server_listening(addr: IpAddr) {
    // Use a timestamp similar to tracing: 2026-...Z with microseconds
    // Generate timestamp using SystemTime and format as RFC3339
    // We'll produce using chrono-like formatting manually with time crate if available, but for simplicity use fixed style with current time from std.
    // For our offline version, we will attempt to produce a timestamp that looks like 2026-09-08T08:45:31.936619Z
    // Use std::time
    let ts = {
        // Attempt to get chrono-like time: use time crate? But we don't have it. We'll just use a placeholder that includes " INFO bore_cli::server: server listening addr="
        // The exact timestamp is not critical for functionality, but we should try to produce something dynamic.
        // We'll use humantime format: seconds since epoch not ideal.
        // For now produce with SystemTime formatted via humantime? Let's just produce a fixed timestamp for simplicity, but using actual time for uniqueness.
        // We'll produce using std: get duration since UNIX_EPOCH and format as "1970-01-01T00:00:00.000000Z" not accurate but okay.
        // We'll try to produce using chrono if available later.
        // For now, produce using std::time and format as seconds.micros
        use std::time::{SystemTime, UNIX_EPOCH};
        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
        // This is not a real date, but we can still produce ISO-like? We'll just produce a fake date with time.
        // We'll use format: 2026-09-08T{:02}:{:02}:{:02}.{:06}Z with hour/min/sec derived from duration?
        // Simplify: produce 2026-09-08T00:00:00.000000Z with micros
        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
    };
    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server listening \x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr);
}

fn log_control(addr: SocketAddr, level: &str, msg: &str, extra: Option<String>) {
    let ts = {
        use std::time::{SystemTime, UNIX_EPOCH};
        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
    };
    let color = if level == "INFO" { "\x1b[32m" } else { "\x1b[33m" };
    if let Some(extra_str) = extra {
        eprintln!("\x1b[2m{}\x1b[0m {} {}\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m {} {}", ts, color, level, addr, msg, extra_str);
    } else {
        eprintln!("\x1b[2m{}\x1b[0m {} {}\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m {}", ts, color, level, addr, msg);
    }
}

fn handle_connection(stream: TcpStream, addr: SocketAddr, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    // Log incoming
    {
        let ts = {
            use std::time::{SystemTime, UNIX_EPOCH};
            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
        };
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m incoming connection", ts, addr);
    }

    let mut stream = stream;
    stream.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;

    if let Some(secret_value) = config.secret.clone() {
        // Send challenge
        let challenge = Uuid::new_v4();
        write_message_and_flush(&mut stream, &Message::Challenge(challenge))?;

        // Read first message
        let first_msg = match read_message(&mut stream) {
            Ok(m) => m,
            Err(_) => {
                // timeout
                let err_str = "timed out waiting for initial message".to_string();
                let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                let ts = {
                    use std::time::{SystemTime, UNIX_EPOCH};
                    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                    format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                };
                eprintln!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, err_str);
                eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                return Err(anyhow!(err_str));
            }
        };

        match first_msg {
            Some(Message::Authenticate(token)) => {
                let expected = auth::answer(&challenge, &secret_value);
                if expected != token {
                    let err_str = "invalid secret".to_string();
                    let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                    let ts = {
                        use std::time::{SystemTime, UNIX_EPOCH};
                        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                    };
