                                let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                                format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                            };
                            eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                            return Err(e);
                        }
                    }
                    _ => return Err(anyhow!("unexpected")),
                }
            }
            Some(Message::Hello(_)) => {
                let err_str = "server requires secret, but no secret was provided".to_string();
                let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                let ts = {
                    use std::time::{SystemTime, UNIX_EPOCH};
