    pub fn read_message(stream: &mut TcpStream) -> Result<Option<Message>> {
        let mut buf = Vec::new();
        let mut byte = [0u8; 1];
        loop {
            let n = stream.read(&mut byte)?;
            if n == 0 {
                if buf.is_empty() {
                    return Ok(None);
