    }

    Ok(())
}

fn run_server(args: ServerArgs) -> Result<()> {
    if args.min_port > args.max_port {
        eprintln!("error: port range is empty");
        eprintln!();
        eprintln!("Usage: bore-cli <COMMAND>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    let bind_tunnels = args.bind_tunnels.unwrap_or(args.bind_addr);
    let config = ServerConfig {
        min_port: args.min_port,
        max_port: args.max_port,
        secret: args.secret,
        bind_addr: args.bind_addr,
        bind_tunnels,
    };

    let control_addr = SocketAddr::new(config.bind_addr, CONTROL_PORT);
    let listener = TcpListener::bind(control_addr).context("failed to bind")?;
    log_server_listening(config.bind_addr);

    let shared = Arc::new(Mutex::new(SharedState {
        allocated_ports: HashMap::new(),
        pending: HashMap::new(),
    }));

    for stream in listener.incoming() {
        match stream {
            Ok(s) => {
                let addr = s.peer_addr().unwrap_or_else(|_| "0.0.0.0:0".parse().unwrap());
                let config_clone = config.clone();
                let shared_clone = shared.clone();
                std::thread::spawn(move || {
                    let _ = handle_connection(s, addr, config_clone, shared_clone);
                });
            }
            Err(e) => {
                eprintln!("accept error: {}", e);
            }
        }
    }
    Ok(())
}

fn run_local(args: LocalArgs) -> Result<()> {
