                                eprintln!("For more information, try '--help'.");
                                std::process::exit(2);
                            }
                        }
                    }
                    other => {
                        eprintln!("error: unexpected argument '{}' found", other);
                        eprintln!();
                        eprintln!("Usage: executable server [OPTIONS]");
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        std::process::exit(2);
                    }
                }
                i += 1;
            }

            if min_port > max_port {
                eprintln!("error: port range is empty");
                eprintln!();
                eprintln!("Usage: bore-cli <COMMAND>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }

            Ok(Cli {
                command: Commands::Server(ServerArgs {
                    min_port,
                    max_port,
                    secret,
                    bind_addr,
                    bind_tunnels,
                }),
            })
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", sub);
            eprintln!();
            eprintln!("Usage: executable <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

struct PendingConn {
    stream: TcpStream,
    addr: SocketAddr,
}

struct SharedState {
    allocated_ports: HashMap<u16, ()>,
    pending: HashMap<Uuid, PendingConn>,
}

#[derive(Clone)]
struct ServerConfig {
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: IpAddr,
    bind_tunnels: IpAddr,
}

fn log_server_listening(addr: IpAddr) {
    let ts = {
        use std::time::{SystemTime, UNIX_EPOCH};
        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
    };
    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server listening \x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr);
}

fn handle_connection(stream: TcpStream, addr: SocketAddr, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    {
        let ts = {
            use std::time::{SystemTime, UNIX_EPOCH};
            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
        };
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m incoming connection", ts, addr);
    }

    let mut stream = stream;
    stream.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;

    if let Some(secret_value) = config.secret.clone() {
        let challenge = Uuid::new_v4();
        write_message_and_flush(&mut stream, &Message::Challenge(challenge))?;

        let first_msg = match read_message(&mut stream) {
            Ok(m) => m,
            Err(_) => {
                let err_str = "timed out waiting for initial message".to_string();
                let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                let ts = {
                    use std::time::{SystemTime, UNIX_EPOCH};
                    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                    format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                };
                eprintln!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, err_str);
                eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                return Err(anyhow!(err_str));
            }
        };

        match first_msg {
            Some(Message::Authenticate(token)) => {
                let expected = auth::answer(&challenge, &secret_value);
                if expected != token {
                    let err_str = "invalid secret".to_string();
                    let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                    let ts = {
                        use std::time::{SystemTime, UNIX_EPOCH};
                        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                    };
                    eprintln!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, err_str);
                    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                    return Err(anyhow!(err_str));
                }
                let second_msg = match read_message(&mut stream) {
                    Ok(m) => m,
                    Err(_) => {
                        let err_str = "timed out waiting for initial message".to_string();
                        let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                        let ts = {
                            use std::time::{SystemTime, UNIX_EPOCH};
                            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                        };
                        eprintln!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, err_str);
                        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                        return Err(anyhow!(err_str));
                    }
                };
                match second_msg {
                    Some(Message::Hello(port)) => {
                        match handle_new_client(stream, addr, port, config, shared) {
                            Ok(_) => {},
                            Err(e) => {
                                let ts = {
                                    use std::time::{SystemTime, UNIX_EPOCH};
                                    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                                    format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                                };
                                let msg = e.to_string();
                                if msg == "port already in use" || msg == "client port number not in allowed range" {
                                    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                                } else {
                                    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                                }
                                return Err(e);
                            }
                        }
                    }
                    Some(Message::Accept(uuid)) => {
                        if let Err(e) = handle_accept(stream, addr, uuid, shared) {
                            let ts = {
                                use std::time::{SystemTime, UNIX_EPOCH};
                                let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                                format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                            };
                            eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                            return Err(e);
                        }
                    }
                    _ => return Err(anyhow!("unexpected")),
                }
            }
            Some(Message::Hello(_)) => {
                let err_str = "server requires secret, but no secret was provided".to_string();
                let _ = write_message_and_flush(&mut stream, &Message::Error(err_str.clone()));
                let ts = {
                    use std::time::{SystemTime, UNIX_EPOCH};
                    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                    format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                };
                eprintln!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, err_str);
                eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                return Err(anyhow!(err_str));
            }
            _ => return Err(anyhow!("unexpected")),
        }
    } else {
        let first_msg = match read_message(&mut stream) {
            Ok(m) => m,
            Err(_) => {
                let ts = {
                    use std::time::{SystemTime, UNIX_EPOCH};
                    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                    format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                };
                eprintln!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited with error \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, "timed out waiting for initial message");
                return Err(anyhow!("timed out waiting for initial message"));
            }
        };
        match first_msg {
            Some(Message::Hello(port)) => {
                match handle_new_client(stream, addr, port, config, shared) {
                    Ok(_) => {},
                    Err(e) => {
                        let ts = {
                            use std::time::{SystemTime, UNIX_EPOCH};
                            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                        };
                        let msg = e.to_string();
                        if msg == "port already in use" || msg == "client port number not in allowed range" {
                            eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                        } else {
                            eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                        }
                        return Err(e);
                    }
                }
            }
            Some(Message::Accept(uuid)) => {
                if let Err(e) = handle_accept(stream, addr, uuid, shared) {
                    let ts = {
                        use std::time::{SystemTime, UNIX_EPOCH};
                        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                    };
                    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
                    return Err(e);
                }
            }
            _ => return Err(anyhow!("unexpected")),
        }
    }
    Ok(())
}

fn handle_new_client(stream: TcpStream, addr: SocketAddr, requested_port: u16, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    let allocated = {
        if requested_port != 0 {
            if requested_port < config.min_port || requested_port > config.max_port {
                let mut s = stream.try_clone()?;
                let _ = write_message_and_flush(&mut s, &Message::Error("client port number not in allowed range".to_string()));
                return Err(anyhow!("client port number not in allowed range"));
            }
            {
                let state = shared.lock().unwrap();
                if state.allocated_ports.contains_key(&requested_port) {
                    drop(state);
                    let mut s = stream.try_clone()?;
                    let _ = write_message_and_flush(&mut s, &Message::Error("port already in use".to_string()));
                    return Err(anyhow!("port already in use"));
                }
            }
            let bind_addr = SocketAddr::new(config.bind_tunnels, requested_port);
            match TcpListener::bind(bind_addr) {
                Ok(l) => {
                    drop(l);
                    let mut state = shared.lock().unwrap();
                    state.allocated_ports.insert(requested_port, ());
                    requested_port
                }
                Err(_) => {
                    let mut s = stream.try_clone()?;
                    let _ = write_message_and_flush(&mut s, &Message::Error("port already in use".to_string()));
                    return Err(anyhow!("port already in use"));
                }
            }
        } else {
            let mut attempts = 0;
            let mut chosen = None;
            loop {
                let candidate = if config.min_port == 0 && config.max_port == 65535 {
                    0
                } else {
                    if attempts < (config.max_port - config.min_port + 1) as usize {
                        config.min_port + (attempts as u16 % (config.max_port - config.min_port + 1))
                    } else {
                        0
                    }
                };
                if candidate != 0 {
                    let state = shared.lock().unwrap();
                    if state.allocated_ports.contains_key(&candidate) {
                        attempts += 1;
                        if attempts > 10000 {
                            break;
                        }
                        continue;
                    }
                }
                let bind_addr = SocketAddr::new(config.bind_tunnels, candidate);
                match TcpListener::bind(bind_addr) {
                    Ok(l) => {
                        let port = l.local_addr()?.port();
                        if port < config.min_port || port > config.max_port {
                            attempts += 1;
                            if attempts > 10000 {
                                break;
                            }
                            continue;
                        }
                        {
                            let mut state = shared.lock().unwrap();
                            if state.allocated_ports.contains_key(&port) {
                                attempts += 1;
                                continue;
                            }
                            state.allocated_ports.insert(port, ());
                        }
                        chosen = Some(port);
                        break;
                    }
                    Err(_) => {
                        attempts += 1;
                        if attempts > 10000 {
                            break;
                        }
                        continue;
                    }
                }
            }
            if let Some(port) = chosen {
                port
            } else {
                let mut s = stream.try_clone()?;
                let _ = write_message_and_flush(&mut s, &Message::Error("no available port".to_string()));
                return Err(anyhow!("no available port"));
            }
        }
    };

    run_client(stream, addr, allocated, config, shared)
}

fn run_client(control_stream: TcpStream, control_addr: SocketAddr, remote_port: u16, config: ServerConfig, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    let mut control_stream = control_stream;
    write_message_and_flush(&mut control_stream, &Message::Hello(remote_port))?;
    {
        let ts = {
            use std::time::{SystemTime, UNIX_EPOCH};
            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
        };
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m new client \x1b[3mhost\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", ts, control_addr, config.bind_tunnels, remote_port);
    }

    let tunnel_addr = SocketAddr::new(config.bind_tunnels, remote_port);
    let tunnel_listener = TcpListener::bind(tunnel_addr)?;

    let control_writer = Arc::new(Mutex::new(control_stream.try_clone()?));

    let writer_clone = control_writer.clone();
    std::thread::spawn(move || {
        loop {
            std::thread::sleep(HEARTBEAT_INTERVAL);
            let mut w = writer_clone.lock().unwrap();
            if write_message_and_flush(&mut *w, &Message::Heartbeat).is_err() {
                break;
            }
        }
    });

    loop {
        let (public_stream, public_addr) = match tunnel_listener.accept() {
            Ok(x) => x,
            Err(_) => break,
        };
        {
            let ts = {
                use std::time::{SystemTime, UNIX_EPOCH};
                let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
            };
            eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m new connection \x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", ts, control_addr, public_addr, remote_port);
        }

        let conn_id = Uuid::new_v4();
        {
            let mut state = shared.lock().unwrap();
            state.pending.insert(conn_id, PendingConn { stream: public_stream, addr: public_addr });
        }

        {
            let mut w = control_writer.lock().unwrap();
            if write_message_and_flush(&mut *w, &Message::Connection(conn_id)).is_err() {
                let mut state = shared.lock().unwrap();
                state.pending.remove(&conn_id);
                break;
            }
        }
    }

    {
        let mut state = shared.lock().unwrap();
        state.allocated_ports.remove(&remote_port);
    }
    Ok(())
}

fn handle_accept(accept_stream: TcpStream, addr: SocketAddr, conn_id: Uuid, shared: Arc<Mutex<SharedState>>) -> Result<()> {
    let pending = {
        let mut state = shared.lock().unwrap();
        state.pending.remove(&conn_id)
    };
    let pending = match pending {
        Some(p) => p,
        None => return Err(anyhow!("no pending")),
    };
    {
        let ts = {
            use std::time::{SystemTime, UNIX_EPOCH};
            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
        };
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m forwarding connection \x1b[3mid\x1b[0m\x1b[2m=\x1b[0m{}", ts, addr, conn_id);
    }

    let public_stream = pending.stream;
    let client_stream = accept_stream;

    let mut public_read = public_stream.try_clone()?;
    let mut public_write = public_stream;
    let mut client_read = client_stream.try_clone()?;
    let mut client_write = client_stream;

    let h1 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match public_read.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if client_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });
    let h2 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match client_read.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if public_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });
    let _ = h1.join();
    let _ = h2.join();

    {
        let ts = {
            use std::time::{SystemTime, UNIX_EPOCH};
            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
        };
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mcontrol\x1b[0m\x1b[1m{{\x1b[0m\x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::server\x1b[0m\x1b[2m:\x1b[0m connection exited", ts, addr);
    }

    Ok(())
}

fn run_server(args: ServerArgs) -> Result<()> {
    if args.min_port > args.max_port {
        eprintln!("error: port range is empty");
        eprintln!();
        eprintln!("Usage: bore-cli <COMMAND>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    let bind_tunnels = args.bind_tunnels.unwrap_or(args.bind_addr);
    let config = ServerConfig {
        min_port: args.min_port,
        max_port: args.max_port,
        secret: args.secret,
        bind_addr: args.bind_addr,
        bind_tunnels,
    };

    let control_addr = SocketAddr::new(config.bind_addr, CONTROL_PORT);
    let listener = TcpListener::bind(control_addr).context("failed to bind")?;
    log_server_listening(config.bind_addr);

    let shared = Arc::new(Mutex::new(SharedState {
        allocated_ports: HashMap::new(),
        pending: HashMap::new(),
    }));

    for stream in listener.incoming() {
        match stream {
            Ok(s) => {
                let addr = s.peer_addr().unwrap_or_else(|_| "0.0.0.0:0".parse().unwrap());
                let config_clone = config.clone();
                let shared_clone = shared.clone();
                std::thread::spawn(move || {
                    let _ = handle_connection(s, addr, config_clone, shared_clone);
                });
            }
            Err(e) => {
                eprintln!("accept error: {}", e);
            }
        }
    }
    Ok(())
}

fn run_local(args: LocalArgs) -> Result<()> {
    let control_addr_str = format!("{}:{}", args.to, CONTROL_PORT);
    let mut control_stream = TcpStream::connect(&control_addr_str).with_context(|| format!("could not connect to {}:{}", args.to, CONTROL_PORT))?;
    let to_clone = args.to.clone();

    let remote_port_allocated: u16;

    if let Some(secret) = args.secret.clone() {
        control_stream.set_read_timeout(Some(Duration::from_secs(3)))?;
        let msg = match read_message(&mut control_stream) {
            Ok(m) => m,
            Err(_) => {
                return Err(anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"));
            }
        };
        match msg {
            Some(Message::Challenge(challenge)) => {
                let token = auth::answer(&challenge, &secret);
                write_message_and_flush(&mut control_stream, &Message::Authenticate(token))?;
                write_message_and_flush(&mut control_stream, &Message::Hello(args.port))?;
                control_stream.set_read_timeout(Some(Duration::from_secs(3)))?;
                let resp = match read_message(&mut control_stream) {
                    Ok(m) => m,
                    Err(_) => {
                        return Err(anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"));
                    }
                };
                match resp {
                    Some(Message::Hello(p)) => remote_port_allocated = p,
                    Some(Message::Error(e)) => return Err(anyhow!("server error: {}", e)),
                    _ => return Err(anyhow!("unexpected message")),
                }
            }
            Some(Message::Hello(_)) => {
                return Err(anyhow!("expected authentication challenge, but no secret was required"));
            }
            Some(Message::Error(e)) => {
                return Err(anyhow!("server error: {}", e));
            }
            _ => return Err(anyhow!("unexpected")),
        }
    } else {
        write_message_and_flush(&mut control_stream, &Message::Hello(args.port))?;
        control_stream.set_read_timeout(Some(Duration::from_secs(3)))?;
        let resp = match read_message(&mut control_stream) {
            Ok(m) => m,
            Err(_) => {
                return Err(anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"));
            }
        };
        match resp {
            Some(Message::Hello(p)) => remote_port_allocated = p,
            Some(Message::Challenge(_)) => {
                return Err(anyhow!("server requires authentication, but no client secret was provided"));
            }
            Some(Message::Error(e)) => {
                return Err(anyhow!("server error: {}", e));
            }
            _ => return Err(anyhow!("unexpected")),
        }
    }

    {
        let ts = {
            use std::time::{SystemTime, UNIX_EPOCH};
            let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
            format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
        };
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mbore_cli::client\x1b[0m\x1b[2m:\x1b[0m connected to server \x1b[3mremote_port\x1b[0m\x1b[2m=\x1b[0m{}", ts, remote_port_allocated);
        eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mbore_cli::client\x1b[0m\x1b[2m:\x1b[0m listening at {}:{}", ts, to_clone, remote_port_allocated);
    }

    control_stream.set_read_timeout(None)?;
    loop {
        let msg = read_message(&mut control_stream)?;
        match msg {
            Some(Message::Connection(conn_id)) => {
                let to = args.to.clone();
                let secret = args.secret.clone();
                let local_host = args.local_host.clone();
                let local_port = args.local_port;
                std::thread::spawn(move || {
                    let ts = {
                        use std::time::{SystemTime, UNIX_EPOCH};
                        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                    };
                    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mproxy\x1b[0m\x1b[1m{{\x1b[0m\x1b[3mid\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::client\x1b[0m\x1b[2m:\x1b[0m new connection", ts, conn_id);
                    if let Err(e) = handle_proxy_connection(to, secret, local_host, local_port, conn_id) {
                        eprintln!("proxy error: {}", e);
                    }
                    let ts2 = {
                        use std::time::{SystemTime, UNIX_EPOCH};
                        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                        format!("2026-09-08T00:00:00.{:06}Z", dur.subsec_micros())
                    };
                    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1mproxy\x1b[0m\x1b[1m{{\x1b[0m\x1b[3mid\x1b[0m\x1b[2m=\x1b[0m{}\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m \x1b[2mbore_cli::client\x1b[0m\x1b[2m:\x1b[0m connection exited", ts2, conn_id);
                });
            }
            Some(Message::Heartbeat) => {}
            Some(Message::Error(e)) => {
                return Err(anyhow!("server error: {}", e));
            }
            None => break,
            _ => {}
        }
    }

    Ok(())
}

fn handle_proxy_connection(to: String, secret: Option<String>, local_host: String, local_port: u16, conn_id: Uuid) -> Result<()> {
    let control_addr_str = format!("{}:{}", to, CONTROL_PORT);
    let mut stream = TcpStream::connect(&control_addr_str)?;
    stream.set_read_timeout(Some(Duration::from_secs(3)))?;

    if let Some(secret_val) = secret {
        let challenge_msg = read_message(&mut stream)?;
        let challenge = match challenge_msg {
            Some(Message::Challenge(c)) => c,
            Some(Message::Error(e)) => return Err(anyhow!("server error: {}", e)),
            _ => return Err(anyhow!("expected challenge")),
        };
        let token = auth::answer(&challenge, &secret_val);
        write_message_and_flush(&mut stream, &Message::Authenticate(token))?;
    }

    write_message_and_flush(&mut stream, &Message::Accept(conn_id))?;

    let local_addr_str = format!("{}:{}", local_host, local_port);
    let local_stream = TcpStream::connect(&local_addr_str)?;

    let mut local_read = local_stream.try_clone()?;
    let mut local_write = local_stream;
    let mut remote_read = stream.try_clone()?;
    let mut remote_write = stream;

    let h1 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match remote_read.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if local_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });
    let h2 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match local_read.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    if remote_write.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });
    let _ = h1.join();
    let _ = h2.join();
    Ok(())
}

fn main() -> Result<()> {
    let cli = parse_args()?;
    match cli.command {
        Commands::Local(args) => {
            if let Err(e) = run_local(args) {
                eprintln!("Error: {}", e);
                let mut source = e.source();
                if source.is_some() {
                    eprintln!();
                    eprintln!("Caused by:");
                    while let Some(s) = source {
                        eprintln!("    {}", s);
                        source = s.source();
                    }
                }
                std::process::exit(1);
            }
        }
        Commands::Server(args) => {
            if let Err(e) = run_server(args) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    }
    Ok(())
}
