mod common {
    use super::protocol::Message;
    use anyhow::Result;
    use std::io::{Read, Write};
    use std::net::TcpStream;

    pub fn read_message(stream: &mut TcpStream) -> Result<Option<Message>> {
        let mut buf = Vec::new();
        let mut byte = [0u8; 1];
        loop {
            let n = stream.read(&mut byte)?;
            if n == 0 {
                if buf.is_empty() {
                    return Ok(None);
                } else {
                    return Err(anyhow::anyhow!("connection closed before null byte"));
                }
            }
            if byte[0] == 0 {
                break;
            }
            buf.push(byte[0]);
        }
        if buf.is_empty() {
            return Ok(None);
        }
        let msg: Message = serde_json::from_slice(&buf)?;
        Ok(Some(msg))
    }

    pub fn write_message(stream: &mut TcpStream, msg: &Message) -> Result<()> {
        let json = serde_json::to_string(msg)?;
        let mut data = json.into_bytes();
        data.push(0);
        stream.write_all(&data)?;
        Ok(())
    }

    pub fn write_message_and_flush(stream: &mut TcpStream, msg: &Message) -> Result<()> {
        write_message(stream, msg)?;
        stream.flush()?;
        Ok(())
    }
}

mod simple_hmac {
    use sha2::{Sha256, Digest};

    pub fn hmac_sha256(key: &[u8], data: &[u8]) -> Vec<u8> {
        const BLOCK_SIZE: usize = 64;
        let mut key_block = vec![0u8; BLOCK_SIZE];
        if key.len() > BLOCK_SIZE {
            let mut hasher = Sha256::new();
            hasher.update(key);
            let hashed = hasher.finalize();
            key_block[..hashed.len()].copy_from_slice(&hashed);
        } else {
            key_block[..key.len()].copy_from_slice(key);
        }
        let mut ipad = vec![0x36u8; BLOCK_SIZE];
        let mut opad = vec![0x5cu8; BLOCK_SIZE];
        for i in 0..BLOCK_SIZE {
            ipad[i] ^= key_block[i];
            opad[i] ^= key_block[i];
        }
        let mut inner = Sha256::new();
        inner.update(&ipad);
        inner.update(data);
        let inner_result = inner.finalize();

        let mut outer = Sha256::new();
        outer.update(&opad);
        outer.update(&inner_result);
        outer.finalize().to_vec()
    }
}

